\midrule
\textbf{item} & \textbf{37.9} & \textbf{37.9} & 34.3 & 16.9 & 24.0 \\
mod.$\times$item & 30.2 & 33.7 & \textbf{36.0} & 14.6 & 17.3 \\
model & 2.8 & 3.1 & 5.4 & 10.7 & 8.5 \\
